#!/bin/sh
# The OBJFAR measurement build (B65 with the far-pointer integrator that
# OBJ65 uses, src/objfar.a generated by tools/mkobjfar.py) from a clean
# checkout of HEAD: it must build, and one objcheck seed must match the
# model. Run by tests/smoke.sh after the smoke tests.
cd "$(dirname "$0")/.." || exit 1
W=$(mktemp -d)
git worktree add -q "$W/wt" HEAD || exit 1
( cd "$W/wt" && mkdir -p build && acme tests/boot.a && ACMEFLAGS=-DOBJFAR=1 python3 tools/fixbranches.py >"$W/build.log" 2>&1 &&
  python3 tests/objcheck.py 1 40 60 | tail -1 ) >"$W/out" 2>&1
r=$?
git worktree remove --force "$W/wt"
if [ $r = 0 ] && grep -q "OK" "$W/out"; then echo "PASS OBJFAR build (clean checkout)"; rm -rf "$W"; exit 0; fi
echo "FAIL OBJFAR build (clean checkout)"; cat "$W/build.log" "$W/out"; rm -rf "$W"; exit 1
